    }

    input:hover {
      border-color: var(--border-strong);
    }

    input:focus-visible {
      outline: 2px solid transparent;
      border-color: var(--primary);
      box-shadow: 0 0 0 4px rgb(23 92 211 / 0.18);
    }

    .field-help,
    .field-error,
    .form-status {
      font-size: 0.94rem;
    }

    .field-help {
      color: var(--text-soft);
    }

    .field-error {
      color: var(--danger);
    }

    .submit-button {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      min-height: 3.3rem;
      margin-top: 0.5rem;
