      border: 0;
      border-radius: 999px;
      background: linear-gradient(180deg, var(--primary) 0%, var(--primary-strong) 100%);
      color: #fff;
      font: inherit;
      font-weight: 700;
      cursor: pointer;
      transition: transform 160ms ease, box-shadow 160ms ease, background 160ms ease;
      box-shadow: 0 16px 30px -18px rgb(23 92 211 / 0.8);
    }

    .submit-button:hover {
      transform: translateY(-1px);
    }

    .submit-button:focus-visible {
      outline: 2px solid transparent;
      box-shadow:
        0 16px 30px -18px rgb(23 92 211 / 0.8),
        0 0 0 4px rgb(23 92 211 / 0.2);
    }

    .form-status {
      min-height: 1.5rem;
      margin: 0;
      font-weight: 600;
      color: var(--success);
    }

    .site-footer {
      margin-top: 1.5rem;
      color: var(--text-soft);
      font-size: 0.95rem;
    }

    @media (max-width: 860px) {
      .hero-grid {
        grid-template-columns: 1fr;
      }

      .feature-list {
        grid-template-columns: 1fr;
      }
    }

    @media (max-width: 480px) {
      .page-shell {
