<body>
  <a class="skip-link" href="#main-content">Skip to main content</a>
  <div id="app"></div>

  <script>
    function escapeHtml(value) {
      return String(value)
        .replace(/&/g, "&amp;")
        .replace(/</g, "&lt;")
        .replace(/>/g, "&gt;")
        .replace(/"/g, "&quot;")
        .replace(/'/g, "&#39;");
    }

    function Header() {
      return `
        <header class="site-header">
          <div class="brand">Acme Support</div>
          <nav aria-label="Support links">
            <a href="#contact-form">Contact support</a>
          </nav>
        </header>
      `;
    }

    function HeroPanel() {
      return `
        <section class="hero-card" aria-labelledby="support-heading">
          <div>
            <p class="eyebrow">Product support</p>
            <h1 id="support-heading">Talk to our support team.</h1>
            <p class="hero-copy">
              Share your issue, account context, or rollout questions and we will route
              your request to the right specialist.
            </p>
          </div>
          <ul class="feature-list" aria-label="Support highlights">
            <li class="feature-item">
              <span class="feature-title">Fast routing</span>
              <span class="feature-text">Requests go directly to billing, product, or technical support.</span>
            </li>
            <li class="feature-item">
              <span class="feature-title">Clear follow-up</span>
              <span class="feature-text">We reply with next steps, timing, and any details we still need.</span>
            </li>
            <li class="feature-item">
              <span class="feature-title">Human help</span>
              <span class="feature-text">Your message reaches a support specialist, not a dead-end queue.</span>
            </li>
          </ul>
        </section>
      `;
    }

    function Field(config, state) {
      var id = config.id;
      var error = state.errors[id] || "";
      var describedBy = [];

      if (config.helpText) {
        describedBy.push(id + "-help");
      }

      if (error) {
        describedBy.push(id + "-error");
      }

      return `
        <div class="form-field">
          <label for="${id}">
            ${escapeHtml(config.label)}
            ${config.required ? '<span class="required-mark" aria-hidden="true">*</span>' : ""}
          </label>
          <input
            id="${id}"
            name="${id}"
            type="${config.type}"
            inputmode="${config.inputMode || ""}"
            autocomplete="${config.autocomplete || ""}"
            placeholder="${escapeHtml(config.placeholder || "")}"
            value="${escapeHtml(state.values[id] || "")}"
            ${config.required ? 'required aria-required="true"' : ""}
            ${error ? 'aria-invalid="true"' : ""}
            ${describedBy.length ? 'aria-describedby="' + describedBy.join(" ") + '"' : ""}
          >
          ${config.helpText ? '<p class="field-help" id="' + id + '-help">' + escapeHtml(config.helpText) + '</p>' : ""}
          ${error ? '<p class="field-error" id="' + id + '-error">' + escapeHtml(error) + '</p>' : ""}
        </div>
      `;
    }

    function ContactForm(state) {
      var fields = [
        {
          id: "fullName",
          label: "Full name",
          type: "text",
          autocomplete: "name",
          placeholder: "Jordan Lee",
          required: true
        },
        {
          id: "email",
          label: "Email address",
          type: "email",
          autocomplete: "email",
          placeholder: "jordan@example.com",
          required: true
        },
        {
          id: "phone",
          label: "Phone number",
          type: "tel",
          autocomplete: "tel",
          inputMode: "tel",
          placeholder: "(555) 123-4567",
          helpText: "Optional. Use digits with an area code, for example (555) 123-4567 or +1 555 123 4567."
        }
      ];

      return `
        <section class="form-card" aria-labelledby="form-title">
          <h2 class="card-title" id="form-title">Send a support request</h2>
          <p class="card-copy">
            Required fields are marked with an asterisk.
          </p>
          <form id="contact-form" novalidate>
            ${fields.map(function (field) { return Field(field, state); }).join("")}
            <button class="submit-button" type="submit">Submit request</button>
            <p class="form-status" id="form-status" aria-live="polite">${escapeHtml(state.statusMessage)}</p>
          </form>
        </section>
      `;
    }

    function Footer() {
      return `
        <footer class="site-footer">
          Support hours: Monday to Friday, 8am to 6pm PT.
        </footer>
      `;
    }

    function App(state) {
      return `
        <div class="page-shell">
          ${Header()}
          <main id="main-content" tabindex="-1">
            <div class="hero-grid">
              ${HeroPanel()}
              ${ContactForm(state)}
            </div>
          </main>
          ${Footer()}
        </div>
      `;
    }

    var state = {
      values: {
        fullName: "",
        email: "",
        phone: ""
      },
      errors: {},
      statusMessage: ""
    };

    var formConfig = {
      fullName: {
        label: "Full name",
        required: true
      },
      email: {
        label: "Email address",
        required: true
      },
      phone: {
        label: "Phone number",
        required: false
      }
    };

    function validate(values) {
      var errors = {};
      var phonePattern = /^[+]?[\d()\-\s]{7,20}$/;

      if (!values.fullName.trim()) {
        errors.fullName = "Enter your full name.";
      }

      if (!values.email.trim()) {
        errors.email = "Enter your email address.";
      } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(values.email)) {
        errors.email = "Enter a valid email address.";
      }

      if (values.phone.trim() && !phonePattern.test(values.phone.trim())) {
        errors.phone = "Enter a valid phone number using digits, spaces, parentheses, or hyphens.";
      }

      return errors;
    }

    function render() {
      document.getElementById("app").innerHTML = App(state);

      var form = document.getElementById("contact-form");
      var inputs = Array.prototype.slice.call(form.querySelectorAll("input"));

      inputs.forEach(function (input) {
        input.addEventListener("input", function (event) {
          state.values[event.target.name] = event.target.value;

          if (state.errors[event.target.name]) {
            state.errors = validate(state.values);
            render();
          }
        });
      });

      form.addEventListener("submit", function (event) {
        event.preventDefault();
        state.statusMessage = "";
        state.errors = validate(state.values);

        if (Object.keys(state.errors).length > 0) {
          render();

          var firstInvalid = document.getElementById(Object.keys(state.errors)[0]);
          if (firstInvalid) {
            firstInvalid.focus();
          }
          return;
        }

        state.statusMessage = "Thanks. Your support request has been submitted.";
        render();
      });
    }

    render();
  </script>
